try {
  const orders = await loadRows('orders');
  const now = dayjs();
  let value = 0;
  for (const row of orders) {
    if (String(row.payment_status || '') === 'paid') continue;
    if (!row.order_date) continue;
    const d = dayjs(row.order_date);
    if (!d.isValid()) continue;
    const days = now.diff(d, 'day', true);
    if (days > 30 && days <= 60) value += Number(row.total_amount) || 0;
  }
  ctx.render(<MiniCard label={t("Overdue 30-60d")} value={value} prefix="$" precision={0} note={t("Unpaid value aging 30 to 60 days.")} popupUid={POPUP_UID} />);
} catch (error) {
