  });
}

function MiniCard({ label, value, prefix, suffix, precision = 0, note, valueColor, navTarget }) {
  // Three fixed-height stacked rows (no flex justify-center) so label / value / note baselines
  // align across every card in a row, regardless of note length or whether note is empty.
  // Whole-card click via ctx.router.navigate (only path allowed inside JSBlock sandbox).
  const handleClick = () => {
    if (!navTarget) return;
    try {
      if (ctx.router && typeof ctx.router.navigate === 'function') {
        ctx.router.navigate(navTarget);
      }
    } catch (_) {}
  };
  const clickable = !!navTarget;
  // theme.useToken is reactive under antd's ConfigProvider, so the card
  // re-renders automatically when the user switches themes.
  const { token } = theme.useToken();
  return (
    <div
      onClick={clickable ? handleClick : undefined}
      style={{
        height: CARD_HEIGHT,
        padding: '6px 12px',
        boxSizing: 'border-box',
        cursor: clickable ? 'pointer' : 'default',
      }}
    >
      <div
        style={{
          height: 20,
          lineHeight: '20px',
          fontSize: 14,
          color: token.colorTextSecondary,
          overflow: 'hidden',
          textOverflow: 'ellipsis',
          whiteSpace: 'nowrap',
        }}
      >
        {label}
      </div>
      <div
        style={{
          height: 32,
          lineHeight: '32px',
          marginTop: 2,
          fontSize: 24,
          fontWeight: 600,
          color: valueColor || token.colorText,
          overflow: 'hidden',
          whiteSpace: 'nowrap',
          textOverflow: 'ellipsis',
        }}
      >
        {prefix ?? ''}{formatNumber(value, precision)}{suffix ?? ''}
      </div>
      <div
        style={{
          height: 36,
          marginTop: 6,
          fontSize: 12,
          color: token.colorTextSecondary,
          lineHeight: '18px',
          display: '-webkit-box',
          WebkitBoxOrient: 'vertical',
          WebkitLineClamp: 2,
          overflow: 'hidden',
        }}
      >
        {note || ''}
      </div>
    </div>
  );
}

