function formatNumber(v, p) {
  if (v == null || v === '') return '';
  const n = Number(v);
  if (Number.isNaN(n)) return String(v);
  return n.toLocaleString('en-US', {
    minimumFractionDigits: p || 0,
    maximumFractionDigits: p || 0,
  });
}

function MiniCard({ label, value, prefix, suffix, precision = 0, note, valueColor, popupUid }) {
