function sleep(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

async function updateRecord(resourceName, id, payload) {
  const res = ctx.makeResource("MultiRecordResource");
  res.setResourceName(resourceName);
  return res.update(id, payload, { refresh: false });
}

async function loadRecord(resourceName, id) {
  const res = ctx.makeResource("MultiRecordResource");
  res.setResourceName(resourceName);
  res.setPageSize(1);
  res.setFilter({
    id: {
      $eq: id,
    },
  });
  await res.refresh();
  const rows = res.getData() || [];
  return rows[0] || null;
}

async function loadRecordUntilStage(resourceName, id, expectedStage) {
  let latestRecord = null;
  for (const delay of [0, 150, 350, 700]) {
    if (delay) {
      await sleep(delay);
    }
    latestRecord = await loadRecord(resourceName, id);
    if (!expectedStage || latestRecord?.stage === expectedStage) {
      return latestRecord;
    }
  }
  return latestRecord;
}

async function refreshBoundResources() {
  const tasks = [ctx.resource?.refresh?.()].filter(Boolean);
  if (!tasks.length) {
    return;
  }
  await Promise.allSettled(tasks);
}

const hostRecord =
  (await ctx.getVar?.("ctx.popup.record")) ||
  (await ctx.getVar?.("ctx.record")) ||
  null;

const h = React.createElement;

const LeadLifecycleCard = () => {
  // theme.useToken is reactive under antd's ConfigProvider, so the card
  // re-renders automatically when the user switches themes.
  const { token } = theme.useToken();
  const [recordState, setRecordState] = useState(hostRecord || null);
  const [runningStage, setRunningStage] = useState("");
  const [messageText, setMessageText] = useState("");
  const currentStage = String(recordState?.stage || hostRecord?.stage || "new");

  const currentMeta =
    stageMeta[currentStage] || { color: "default", label: currentStage || "-" };

  useEffect(() => {
    let active = true;

    const refreshRecord = async () => {
      if (!hostRecord?.id) {
        return;
      }
      try {
        const nextRecord = await loadRecord("leads", hostRecord.id);
        if (active && nextRecord) {
          setRecordState(nextRecord);
        }
      } catch (error) {
        // Keep the last known local state when background refresh fails.
      }
    };

    refreshRecord();
    return () => {
      active = false;
    };
  }, []);

  const helperText = useMemo(() => {
    if (currentStage === "new") {
      return t("Start here, then move the lead forward whenever contact begins.");
    }
    if (currentStage === "contacted") {
      return t("You can jump ahead once requirements are clear, or move it back if needed.");
    }
    if (currentStage === "qualified") {
      return t("Requirements are confirmed. Move straight to proposal or any later outcome when appropriate.");
    }
    if (currentStage === "proposal") {
      return t("The proposal stage can jump forward to negotiation, won, or lost at any time.");
    }
    if (currentStage === "negotiation") {
      return t("Negotiation is active. Move directly to won, lost, or any earlier step if the process resets.");
    }
    if (currentStage === "won") {
      return t("This lead is marked won. You can still move it back to an earlier stage if the deal changes.");
    }
    if (currentStage === "lost") {
      return t("Lost leads can be reopened by jumping back to any working stage.");
    }
    return t("Pick any target stage below to move this lead immediately.");
  }, [currentStage]);

  const handleStageChange = async (nextStage) => {
    if (!hostRecord?.id) {
      ctx.message?.error?.(t("Lead record is unavailable."));
      return;
    }

    if (nextStage === currentStage) {
      return;
    }

    setRunningStage(nextStage);
    setMessageText("");
    const optimisticRecord = {
      ...(recordState || hostRecord || {}),
      stage: nextStage,
    };
    setRecordState(optimisticRecord);
    try {
      await updateRecord("leads", hostRecord.id, { stage: nextStage });
      const nextRecord =
        (await loadRecordUntilStage("leads", hostRecord.id, nextStage)) ||
        optimisticRecord;
      setRecordState({
        ...optimisticRecord,
        ...nextRecord,
        stage: nextRecord?.stage || nextStage,
      });
      await refreshBoundResources();
      const nextMeta = stageMeta[nextStage] || { label: nextStage };
      const successText =
        ((nextRecord?.lead_name || hostRecord?.lead_name || t("Lead")) +
          t(" moved to ") +
          nextMeta.label +
          ".");
      setMessageText(successText);
      ctx.notification?.success?.({
        message: t("Lead updated"),
        description: successText,
      });
    } catch (error) {
      const nextError = error?.message || t("Failed to update lead stage.");
      setMessageText(nextError);
      ctx.message?.error?.(nextError);
    } finally {
      setRunningStage("");
    }
  };

  return h(
    Card,
    {
      title: t("Lifecycle actions"),
      style: {
        borderRadius: token.borderRadiusLG,
        border: `1px solid ${token.colorBorderSecondary}`,
        background: `linear-gradient(180deg, ${token.colorBgContainer} 0%, ${token.colorBgElevated} 100%)`,
      },
      extra: h(Tag, { color: currentMeta.color }, currentMeta.label),
    },
    h(
      "div",
      { style: { display: "grid", gap: 14 } },
      h(
        Descriptions,
        { column: 1, size: "small", bordered: true },
        h(
          Descriptions.Item,
          { label: t("Lead") },
          recordState?.lead_name || hostRecord?.lead_name || "-"
        ),
        h(Descriptions.Item, { label: t("Current stage") }, currentMeta.label),
        h(
          Descriptions.Item,
          { label: t("How it works") },
          t("All stages are listed below in order. The current stage is disabled, and you can jump directly to any other stage.")
        )
      ),
      h(
        Paragraph,
        { type: "secondary", style: { marginBottom: 0 } },
        helperText
      ),
      messageText
        ? h(Alert, {
            type:
              messageText.toLowerCase().includes("failed") ||
              messageText.toLowerCase().includes("unavailable")
                ? "error"
                : "success",
            showIcon: true,
            message: messageText,
          })
        : null,
      h(
        Space,
        { wrap: true, size: 8 },
        ...orderedStages.flatMap((stage, index) => {
          const isCurrent = stage.value === currentStage;
          const isBusy = runningStage === stage.value;
          const buttonNode = h(
            Button,
            {
              key: stage.value,
              type: isCurrent || stage.value === "won" ? "primary" : "default",
              danger: stage.value === "lost",
              disabled: isCurrent,
              loading: isBusy,
              style: {
                opacity: 1,
                fontWeight: isCurrent ? 600 : 500,
              },
              onClick: () => handleStageChange(stage.value),
            },
            (index + 1) + ". " + stage.title
          );
          if (index === orderedStages.length - 1) {
            return [buttonNode];
          }
          return [
            buttonNode,
            h(
              "span",
              { key: stage.value + "-arrow", style: arrowStyle },
              "->"
            ),
          ];
        })
      ),
    )
  );
};

ctx.render(h(LeadLifecycleCard));

