}

function rowSubtitle(row) {
  return [row.customer?.customer_name, personName(row.owner)].filter(Boolean).join(' · ') || t('Quotation draft');
}

function rowTags(row) {
  const tags=[]; pushTag(tags, titleCase(row.quotation_status), statusColor(row.quotation_status)); pushTag(tags, formatAmount(row.total_amount, row.currency_code)); if (row.quotation_date) pushTag(tags, t('Issued: ') + formatDate(row.quotation_date)); if (row.valid_until) pushTag(tags, t('Valid until: ') + formatDate(row.valid_until)); return tags;
}

function includeRow(row) {
  return !['accepted','converted','rejected'].includes(String(row.quotation_status || ''));
