const currentUser = ctx.user ?? ctx.auth?.user ?? null;
const DETAIL_UID = '71yqlgwvrq8';
const APPENDS = ["asset","vendor"];
const PAGE_SIZE = 6;

function parseDate(value) {
  if (!value) return null;
  const parsed = dayjs(value);
  return parsed.isValid() ? parsed : null;
}

function formatDate(value, format = 'MMM DD, YYYY') {
  const parsed = parseDate(value);
  return parsed ? parsed.format(format) : '-';
}

function titleCase(text) {
  return String(text || '')
    .split('_')
    .filter(Boolean)
    .map((part) => part.charAt(0).toUpperCase() + part.slice(1))
    .join(' ');
}

function statusColor(value) {
  const key = String(value || '');
  const map = {
    key: 'gold',
    active: 'success',
    prospective: 'processing',
    paused: 'warning',
    lost: 'default',
    new: 'default',
    contacted: 'blue',
    qualified: 'cyan',
    proposal: 'purple',
    negotiation: 'volcano',
    won: 'success',
    draft: 'default',
    sent: 'processing',
    approved: 'success',
    accepted: 'success',
    converted: 'success',
    rejected: 'default',
    pending_assignment: 'default',
    in_progress: 'processing',
    waiting_customer: 'gold',
    waiting_internal: 'purple',
    resolved: 'success',
    closed: 'success',
    cancelled: 'default',
    not_started: 'default',
    planning: 'blue',
    on_hold: 'warning',
    delayed: 'error',
    todo: 'default',
    blocked: 'error',
    idle: 'default',
    assigned: 'processing',
    repair: 'volcano',
    retired: 'default',
    paid: 'success',
    unpaid: 'error',
    partial: 'warning',
    pending: 'warning',
    ready: 'processing',
    completed: 'success',
    resignation: 'volcano',
    termination: 'error',
    transfer: 'blue',
    retirement: 'gold',
    inspection: 'blue',
    repair_service: 'volcano',
    vendor_repair: 'purple',
  };
  return map[key] || 'default';
}

function formatAmount(value, currency) {
  const amount = Number(value || 0);
  if (!Number.isFinite(amount)) return '-';
  if (currency) return currency + ' ' + amount.toLocaleString();
  return amount.toLocaleString();
}

function pushTag(tags, text, color = 'default') {
  if (!text) return;
  tags.push({ text, color });
}

function personName(person) {
  if (!person) return '';
  return person.nickname || person.username || person.full_name || person.employee_no || '';
}

async function loadRows() {
  const resource = ctx.makeResource('MultiRecordResource');
  resource.setResourceName('asset_maintenances');
  resource.setPageSize?.(200);
  if (APPENDS.length) {
    resource.setAppends?.(APPENDS);
  }
  await resource.refresh();
  return resource.getData?.() || [];
}

async function openDetails(row) {
  await ctx.openView(DETAIL_UID, {
    filterByTk: row.id,
  });
}

function rowTitle(row) {
  return row.asset?.asset_name || (t('Maintenance #') + row.id);
}

function rowSubtitle(row) {
  return [row.vendor?.vendor_name, row.asset?.asset_no].filter(Boolean).join(' · ') || t('Maintenance record');
}

function rowTags(row) {
  const tags=[]; pushTag(tags, titleCase(row.maintenance_type), statusColor(row.maintenance_type)); pushTag(tags, titleCase(row.maintenance_status), statusColor(row.maintenance_status)); pushTag(tags, formatAmount(row.maintenance_cost)); if (row.repair_sent_date) pushTag(tags, t('Sent: ') + formatDate(row.repair_sent_date)); return tags;
}

function includeRow(row) {
  return String(row.maintenance_status || '') !== 'completed';
}

function compareRows(a, b) {
  return dayjs(b.repair_sent_date || 0).valueOf() - dayjs(a.repair_sent_date || 0).valueOf();
}

function headerNote(items) {
  return items.length ? t('Assets currently under repair, inspection, or vendor handling') : t('No maintenance records need attention.');
}

