const t = (k, o) => ctx.t(k, { ns: 'nb_demo', ...(o || {}) });
const React = ctx.libs.React;
const { useMemo, useState } = React;
const dayjs = ctx.libs.dayjs;
const { Button, Card, Empty, List, Space, Tag, Typography, theme } = ctx.libs.antd;
const currentUser = ctx.user ?? ctx.auth?.user ?? null;
const DETAIL_UID = 'tplvprojeview';
const APPENDS = ["customer","project_owner"];
const PAGE_SIZE = 6;

function parseDate(value) {
  if (!value) return null;
  const parsed = dayjs(value);
  return parsed.isValid() ? parsed : null;
}

function formatDate(value, format = 'MMM DD, YYYY') {
  const parsed = parseDate(value);
  return parsed ? parsed.format(format) : '-';
}

function titleCase(text) {
  return String(text || '')
    .split('_')
    .filter(Boolean)
    .map((part) => part.charAt(0).toUpperCase() + part.slice(1))
    .join(' ');
}

function statusColor(value) {
  const key = String(value || '');
  const map = {
    key: 'gold',
    active: 'success',
    prospective: 'processing',
    paused: 'warning',
    lost: 'default',
    new: 'default',
    contacted: 'blue',
    qualified: 'cyan',
    proposal: 'purple',
    negotiation: 'volcano',
    won: 'success',
    draft: 'default',
    sent: 'processing',
    approved: 'success',
    accepted: 'success',
    converted: 'success',
    rejected: 'default',
    pending_assignment: 'default',
    in_progress: 'processing',
    waiting_customer: 'gold',
    waiting_internal: 'purple',
    resolved: 'success',
    closed: 'success',
    cancelled: 'default',
    not_started: 'default',
    planning: 'blue',
    on_hold: 'warning',
    delayed: 'error',
    todo: 'default',
    blocked: 'error',
    idle: 'default',
    assigned: 'processing',
    repair: 'volcano',
    retired: 'default',
    paid: 'success',
    unpaid: 'error',
    partial: 'warning',
    pending: 'warning',
    ready: 'processing',
    completed: 'success',
    resignation: 'volcano',
    termination: 'error',
    transfer: 'blue',
    retirement: 'gold',
    inspection: 'blue',
    repair_service: 'volcano',
    vendor_repair: 'purple',
  };
  return map[key] || 'default';
}

function formatAmount(value, currency) {
  const amount = Number(value || 0);
  if (!Number.isFinite(amount)) return '-';
  if (currency) return currency + ' ' + amount.toLocaleString();
  return amount.toLocaleString();
}

function pushTag(tags, text, color = 'default') {
  if (!text) return;
  tags.push({ text, color });
}

function personName(person) {
  if (!person) return '';
  return person.nickname || person.username || person.full_name || person.employee_no || '';
}

async function loadRows() {
  const resource = ctx.makeResource('MultiRecordResource');
  resource.setResourceName('projects');
  resource.setPageSize?.(200);
  if (APPENDS.length) {
    resource.setAppends?.(APPENDS);
  }
  await resource.refresh();
  return resource.getData?.() || [];
}

async function openDetails(row) {
  await ctx.openView(DETAIL_UID, {
    filterByTk: row.id,
  });
}

function rowTitle(row) {
  return row.project_name || row.project_no || ('#' + row.id);
}

function rowSubtitle(row) {
  return [row.project_no, row.customer?.customer_name].filter(Boolean).join(' · ') || t('Delayed project');
}

function rowTags(row) {
  const tags=[]; pushTag(tags, titleCase(row.project_status), statusColor(row.project_status)); pushTag(tags, titleCase(row.priority_level), statusColor(row.priority_level)); if (row.planned_end_date) pushTag(tags, t('Plan: ') + formatDate(row.planned_end_date), 'error'); if (row.project_progress != null) pushTag(tags, t('Progress: ') + String(row.project_progress) + '%'); return tags;
}

function includeRow(row) {
  return Boolean(row.planned_end_date) && dayjs(row.planned_end_date).isBefore(dayjs(), 'day') && !['completed','cancelled'].includes(String(row.project_status || ''));
}

function compareRows(a, b) {
  return dayjs(a.planned_end_date || 0).valueOf() - dayjs(b.planned_end_date || 0).valueOf();
}

function headerNote(items) {
  return items.length ? (items.length + t(' projects have passed their planned end date')) : t('No delayed projects.');
}

function PagedListPanel({ items }) {
  // theme.useToken is reactive under antd's ConfigProvider, so the card
  // re-renders automatically when the user switches themes.
  const { token } = theme.useToken();
  const [page, setPage] = useState(1);
  const visibleItems = useMemo(() => items.slice(0, page * PAGE_SIZE), [items, page]);
  const hasMore = visibleItems.length < items.length;

  return (
    <>
      <div style={{ padding: '6px 10px 12px' }}>
        <Space size={12} style={{ justifyContent: 'space-between', width: '100%', alignItems: 'flex-start' }}>
          <div>
            <Typography.Text strong>Delayed projects</Typography.Text>
            <Typography.Text type="secondary" style={{ display: 'block', fontSize: 12, marginTop: 2 }}>
              {headerNote(items)}
            </Typography.Text>
          </div>
          <Tag color="red">{items.length}</Tag>
        </Space>
      </div>

      {items.length ? (
        <>
          <List
          dataSource={visibleItems}
          split={false}
          renderItem={(row) => (
            <List.Item style={{ padding: '0 8px 10px' }}>
              <button
                type="button"
                onClick={() => openDetails(row)}
                style={{
                  width: '100%',
                  textAlign: 'left',
                  border: `1px solid ${token.colorBorderSecondary}`,
                  background: token.colorBgContainer,
                  borderRadius: token.borderRadiusLG,
                  padding: '14px 16px',
                  cursor: 'pointer',
                  boxShadow: token.boxShadowCard,
                }}
              >
                <Space size={12} style={{ display: 'flex', justifyContent: 'space-between', width: '100%', alignItems: 'flex-start' }}>
                  <div style={{ minWidth: 0, flex: 1 }}>
                    <Typography.Text strong ellipsis style={{ display: 'block', fontSize: 14 }}>
                      {rowTitle(row)}
                    </Typography.Text>
                    <Typography.Text type="secondary" ellipsis style={{ display: 'block', marginTop: 4, fontSize: 12 }}>
                      {rowSubtitle(row)}
                    </Typography.Text>
                    <Space size={[6, 6]} wrap style={{ marginTop: 10 }}>
                      {rowTags(row).map((tag, index) => (
                        <Tag key={index} color={tag.color || 'default'}>{tag.text}</Tag>
                      ))}
                    </Space>
                  </div>
                  <Button type="link" size="small" onClick={(event) => { event.stopPropagation(); openDetails(row); }}>
                    {t('View')}
                  </Button>
                </Space>
              </button>
            </List.Item>
          )}
        />
          {hasMore ? (
            <div style={{ padding: '0 8px 10px' }}>
              <Button block onClick={() => setPage((current) => current + 1)}>
                {t('Load more')}
              </Button>
            </div>
          ) : null}
        </>
      ) : (
        <div style={{ padding: '18px 8px 10px' }}>
          <Empty image={Empty.PRESENTED_IMAGE_SIMPLE} description={t('No delayed projects')} />
        </div>
      )}
    </>
  );
}

try {
  const rows = await loadRows();
  const items = rows
    .filter((row) => includeRow(row))
    .sort(compareRows);

  ctx.render(<PagedListPanel items={items} />);
} catch (error) {
  ctx.render(
    <div style={{ padding: 12 }}>
        <Typography.Text type="secondary">Delayed projects is temporarily unavailable.</Typography.Text>
      </div>
  );
}

