function leaveDays(start, end) {
  if (!start || !end) return 0;
  const s = dayjs(start);
  const e = dayjs(end);
  if (!s.isValid() || !e.isValid()) return 0;
  return Math.max(e.startOf('day').diff(s.startOf('day'), 'day') + 1, 0);
}

