      const d = dayjs(row.start_time);
      return d.isValid() && d.isSame(now, 'month');
    })
    .reduce((sum, row) => sum + leaveDays(row.start_time, row.end_time), 0);
  ctx.render(<MiniCard label={t("Leave days this month")} value={total} suffix="d" precision={1} note={t("Sum of leave days this month.")} popupUid={POPUP_UID} />);
