function calcLineSubtotal(item) {
  const quantity = Math.max(0, toNumber(item.quantity_value));
  const parameterSurcharge = calcParameterSurcharge(item);
  const accessorySurcharge = calcAccessorySurcharge(item);
  const unitPrice =
    toNumber(item.base_unit_price) +
    parameterSurcharge +
    toNumber(item.service_surcharge);
  const discount = toNumber(item.item_discount);
  return round2(Math.max(0, quantity * unitPrice + accessorySurcharge - discount));
}

function calcSummary(form, items) {
  const subtotal = round2(
    items.reduce((sum, item) => sum + calcLineSubtotal(item), 0),
  );
  const discountAmount = round2(toNumber(form.discount_amount));
  const taxableBase = round2(Math.max(0, subtotal - discountAmount));
  const taxAmount = round2(taxableBase * (toNumber(form.tax_rate) / 100));
  const shippingFee = round2(toNumber(form.shipping_fee));
  const otherFee = round2(toNumber(form.other_fee));
  const total = round2(taxableBase + taxAmount + shippingFee + otherFee);

  return {
    subtotal,
    discountAmount,
    taxableBase,
    taxAmount,
    shippingFee,
    otherFee,
    total,
  };
}

function normalizePanelKeys(keys) {
  if (Array.isArray(keys)) {
    return keys.filter(Boolean);
  }
  if (keys) {
    return [keys];
  }
  return [];
}

function ensurePanelOpen(item, panelKey) {
  const current = normalizePanelKeys(item?.openPanels);
  return current.includes(panelKey) ? current : [...current, panelKey];
}

function normalizeCreatedRecord(response) {
  return response?.data?.data || response?.data || response || null;
}

function buildLocalKey(prefix, id) {
  const suffix = id ? String(id) : Date.now() + '-' + Math.random().toString(36).slice(2, 7);
  return prefix + '-' + suffix;
}

async function listRecords(resourceName, options = {}) {
  const res = ctx.makeResource('MultiRecordResource');
  res.setResourceName(resourceName);
  res.setPageSize(options.pageSize || 200);
  if (options.fields) {
    res.setFields(options.fields);
  }
  if (options.appends) {
    res.setAppends(options.appends);
  }
  if (options.sort) {
    res.setSort(options.sort);
  }
  if (options.filter) {
    res.setFilter(options.filter);
  }
  await res.refresh();
  return res.getData() || [];
}

async function createRecord(resourceName, payload) {
  const res = ctx.makeResource('MultiRecordResource');
  res.setResourceName(resourceName);
  return res.create(payload, { refresh: false });
}

async function updateRecord(resourceName, id, payload) {
  const res = ctx.makeResource('MultiRecordResource');
  res.setResourceName(resourceName);
  return res.update(id, payload, { refresh: false });
}

async function destroyRecord(resourceName, target) {
  const res = ctx.makeResource('MultiRecordResource');
  res.setResourceName(resourceName);
  return res.destroy(target);
}

function formatMoney(currencyCode, value) {
  try {
    return new Intl.NumberFormat('zh-CN', {
      style: 'currency',
      currency: currencyCode || 'CNY',
      minimumFractionDigits: 2,
      maximumFractionDigits: 2,
    }).format(toNumber(value));
  } catch (error) {
    return round2(value).toFixed(2);
  }
}

