        return left.is_primary ? -1 : 1;
      });
    const defaultContact = customerContacts[0] || null;

    setForm((prev) => ({
      ...prev,
      customer_id: customerId,
      contact_id: defaultContact?.id || null,
      customer_address_snapshot: customer?.address || '',
      contact_email_snapshot: defaultContact?.email || '',
      contact_phone_snapshot: defaultContact?.phone || '',
    }));
  };

  const handleContactChange = (contactId) => {
    const contact = availableContacts.find((entry) => String(entry.id) === String(contactId)) || null;
    setForm((prev) => ({
      ...prev,
      contact_id: contactId,
      contact_email_snapshot: contact?.email || '',
      contact_phone_snapshot: contact?.phone || '',
    }));
  };

  const handleProductChange = (localKey, productId) => {
    const product = products.find((entry) => String(entry.id) === String(productId)) || null;
    updateItem(localKey, (current) => ({
      ...current,
      product_id: productId,
      product_name_snapshot: product?.product_name || '',
      product_no_snapshot: product?.product_no || '',
      product_type_snapshot: product?.product_type || '',
      pricing_mode_snapshot: product?.pricing_mode || 'manual',
      unit_name: product?.unit_name || '',
      quantity_value: toNumber(current.quantity_value) > 0 ? current.quantity_value : 1,
      base_unit_price: toNumber(product?.base_price),
    }));
  };

  const handleAccessoryProductChange = (itemKey, accessoryKey, productId) => {
    const product = products.find((entry) => String(entry.id) === String(productId)) || null;
    updateAccessory(itemKey, accessoryKey, {
      accessory_product_id: productId,
      accessory_name_snapshot: product?.product_name || '',
      unit_price: toNumber(product?.base_price),
    });
  };

  const validItems = items.filter((item) => item.product_id && toNumber(item.quantity_value) > 0);
  const previewItems = validItems;
  const startedItems = items.filter(itemHasContent);
  const hasIncompleteItems = startedItems.some((item) => !isItemComplete(item));
  const canSave = Boolean(
    currentUser?.id &&
      form.quotation_date &&
      form.valid_until &&
      form.customer_id &&
      form.contact_id &&
      validItems.length > 0 &&
      !hasIncompleteItems &&
      !editLocked &&
      !saving,
  );
  const canPreview = Boolean(form.customer_id && previewItems.length > 0);

  const handlePrintQuotation = () => {
    try {
      const element = ctx.element;
      const ownerDocumentKey = 'owner' + 'Document';
      const defaultViewKey = 'default' + 'View';
      const doc = element ? element[ownerDocumentKey] : null;
      const view = doc ? doc[defaultViewKey] : null;
      const body = doc?.body;
      const previewNode = previewPrintRef.current;

      if (!doc || !view || !body || !previewNode) {
        throw new Error('Print is not available in the current view.');
      }

      const existingHost = body.querySelector('.quotation-print-host');
      if (existingHost) {
        existingHost.remove();
      }

      const printHost = doc.createElement('div');
      printHost.className = 'quotation-print-host';
      printHost.innerHTML = previewNode.innerHTML;
      body.appendChild(printHost);

      const cleanup = () => {
        body.classList.remove('quotation-preview-printing');
        const host = body.querySelector('.quotation-print-host');
        if (host) {
          host.remove();
        }
      };

      body.classList.add('quotation-preview-printing');
      view.addEventListener?.('afterprint', cleanup, { once: true });
      view.print();
      view.setTimeout?.(cleanup, 1000);
    } catch (error) {
      const nextError = error?.message || 'Failed to open print preview.';
      setErrorText(nextError);
      ctx.message?.error?.(nextError);
    }
  };

  const handleSave = async () => {
    if (!currentUser?.id) {
      setErrorText('Current user could not be identified. Please sign in again and retry.');
      return;
    }
    if (editLocked) {
      setErrorText('This quotation can only be edited while it is in Draft or Pending approval.');
      return;
    }
    if (!form.quotation_date || !form.valid_until) {
      setErrorText('Please complete quotation date and valid until before saving.');
      return;
    }
    if (!form.customer_id || !form.contact_id) {
      setErrorText('Please select a customer and contact before saving the quotation.');
      return;
    }
    if (hasIncompleteItems) {
      setErrorText('Some quotation lines are incomplete. Please complete required product and quantity fields.');
      return;
    }
    if (validItems.length === 0) {
      setErrorText('Please add at least one valid quotation line.');
      return;
    }

    setSaving(true);
    setErrorText('');

    try {
      const nextStatus = isEditMode ? currentStatus : 'draft';
      const quotationPayload = {
        quotation_date: form.quotation_date,
        valid_until: form.valid_until,
        currency_code: form.currency_code || 'USD',
        quotation_status: nextStatus,
        pricing_snapshot_version: toNumber(form.pricing_snapshot_version) || 1,
        customer_id: form.customer_id,
        contact_id: form.contact_id,
        owner_id: loadedQuotation?.owner_id || currentUser.id,
        customer_address_snapshot: form.customer_address_snapshot || '',
        contact_email_snapshot: form.contact_email_snapshot || '',
        contact_phone_snapshot: form.contact_phone_snapshot || '',
        subtotal_amount: summary.subtotal,
        discount_amount: summary.discountAmount,
        tax_rate: toNumber(form.tax_rate),
        tax_amount: summary.taxAmount,
        shipping_fee: summary.shippingFee,
        other_fee: summary.otherFee,
        total_amount: summary.total,
        payment_terms: form.payment_terms || '',
        delivery_cycle: form.delivery_cycle || '',
        warranty_terms: form.warranty_terms || '',
        special_terms: form.special_terms || '',
        remark: form.remark || '',
      };

      const quotationResponse = isEditMode
        ? await updateRecord('quotations', editingQuotationId, quotationPayload)
        : await createRecord('quotations', quotationPayload);
      const quotationRecord = normalizeCreatedRecord(quotationResponse);
      const quotationId = isEditMode ? editingQuotationId : quotationRecord?.id;

      if (!quotationId) {
        throw new Error('Quotation header was saved, but the returned record id is missing.');
      }

      if (isEditMode) {
        for (const accessoryId of loadedAccessoryIds) {
          await destroyRecord('quotation_item_accessories', accessoryId);
        }
        for (const parameterId of loadedParameterIds) {
          await destroyRecord('quotation_item_parameters', parameterId);
        }
        for (const itemId of loadedItemIds) {
          await destroyRecord('quotation_items', itemId);
        }
      }

      for (let index = 0; index < validItems.length; index += 1) {
        const item = validItems[index];
        const parameterSummary = buildParameterSummary(item);
        const parameterSurcharge = calcParameterSurcharge(item);
        const accessorySurcharge = calcAccessorySurcharge(item);
        const itemResponse = await createRecord('quotation_items', {
          quotation_id: quotationId,
          product_id: item.product_id,
          product_name_snapshot: item.product_name_snapshot || '',
          product_no_snapshot: item.product_no_snapshot || '',
          product_type_snapshot: item.product_type_snapshot || '',
          pricing_mode_snapshot: item.pricing_mode_snapshot || 'manual',
          quantity_value: toNumber(item.quantity_value),
          unit_name: item.unit_name || '',
          base_unit_price: round2(item.base_unit_price),
          parameter_surcharge: parameterSurcharge,
          accessory_surcharge: accessorySurcharge,
          service_surcharge: round2(item.service_surcharge),
          item_discount: round2(item.item_discount),
          tax_rate: toNumber(form.tax_rate),
          subtotal_amount: calcLineSubtotal(item),
          parameter_summary: parameterSummary,
          service_summary: item.service_summary || '',
          item_remark: item.item_remark || '',
          sort_order: index + 1,
        });
        const itemRecord = normalizeCreatedRecord(itemResponse);
        const quotationItemId = itemRecord?.id;

        if (!quotationItemId) {
          throw new Error('Quotation item was saved, but the returned record id is missing.');
        }

        for (const parameter of item.parameters || []) {
          if (!parameter.parameter_name && !parameter.parameter_code && !parameter.parameter_display_value && !parameter.parameter_value) {
            continue;
          }
          await createRecord('quotation_item_parameters', {
            quotation_item_id: quotationItemId,
            parameter_name: parameter.parameter_name || '',
            parameter_code: parameter.parameter_code || '',
            parameter_value: parameter.parameter_value || '',
            parameter_display_value: parameter.parameter_display_value || parameter.parameter_value || '',
            price_adjustment_mode: parameter.price_adjustment_mode || 'none',
            price_adjustment_value: round2(parameter.price_adjustment_value),
            price_impact_amount: calcParameterImpact(parameter, item.base_unit_price),
          });
        }

        for (const accessory of item.accessories || []) {
          if (!accessory.accessory_name_snapshot && !accessory.accessory_product_id) {
            continue;
          }
          await createRecord('quotation_item_accessories', {
            quotation_item_id: quotationItemId,
            accessory_product_id: accessory.accessory_product_id,
            accessory_name_snapshot: accessory.accessory_name_snapshot || '',
            quantity_value: toNumber(accessory.quantity_value),
            unit_price: round2(accessory.unit_price),
            subtotal_amount: calcAccessorySubtotal(accessory),
          });
        }
      }

      const quotationNo =
        quotationRecord?.quotation_no ||
        quotationRecord?.quotationNo ||
        loadedQuotation?.quotation_no ||
        String(quotationId);

      const nextSaveResult = {
        quotationId,
        quotationNo,
        itemCount: validItems.length,
        totalAmount: summary.total,
        viewPath: currentStatusPath,
      };

      setSaveResult(nextSaveResult);
      setLoadedQuotation((prev) => ({
        ...(prev || {}),
        id: quotationId,
        quotation_no: quotationNo,
        quotation_status: nextStatus,
        owner_id: loadedQuotation?.owner_id || currentUser.id,
      }));
      ctx.notification?.success?.({
        message: isEditMode ? 'Quotation updated' : 'Quotation saved',
        description: buildSuccessViewNode(
          isEditMode ? 'Quotation updated successfully.' : 'Quotation draft created successfully.',
          currentStatusPath,
        ),
      });
      if (isEditMode) {
        setPreviewOpen(false);
        setReloadToken((prev) => prev + 1);
      } else {
        resetDraft();
        setSaveResult(nextSaveResult);
      }
    } catch (error) {
      const nextError = error?.message || (isEditMode ? 'Failed to update quotation.' : 'Failed to create quotation.');
      setErrorText(nextError);
      ctx.message?.error?.(nextError);
    } finally {
      setSaving(false);
    }
  };

  if (loading) {
    return (
      <div style={{ padding: 80, textAlign: 'center' }}>
        <Spin size="large" />
      </div>
    );
  }

  const money = (value) => formatMoney(form.currency_code, value);
  const accessoryProducts = products.filter((product) => product.product_type === 'accessory');
  const previewCustomerName = selectedCustomer?.customer_name || '-';
  const previewContactName = selectedContact?.full_name || '-';
  const previewOwnerName = currentUser?.nickname || currentUser?.username || (currentUser?.id ? '#' + currentUser.id : '-');
  return (
    <div className="quotation-workspace" style={{ padding: 24, minHeight: '100%' }}>
      <style>{`
        .quotation-workspace {
          min-height: 100%;
          background:
            radial-gradient(circle at top left, rgba(22, 119, 255, 0.08), transparent 26%),
            ${token.colorBgLayout};
          border-radius: 28px;
          padding: 24px;
        }
        .quotation-soft-card.ant-card {
          border: 1px solid ${token.colorBorderSecondary};
          border-radius: 22px;
          box-shadow: ${token.boxShadowCard};
          background: ${token.colorBgContainer};
        }
        .quotation-soft-card .ant-card-head {
          border-bottom: 1px solid ${token.colorBorderSecondary};
        }
        .quotation-soft-card .ant-card-head-title {
          font-weight: 700;
          color: ${token.colorTextHeading};
        }
        .quotation-line-card.ant-card {
          border: 1px solid ${token.colorBorderSecondary};
          border-radius: 18px;
          box-shadow: ${token.boxShadowCard};
          background: ${token.colorBgContainer};
        }
        .quotation-summary-card.ant-card {
          border: 1px solid ${token.colorPrimaryBorder};
          border-radius: 24px;
          box-shadow: ${token.boxShadowCard};
          background: ${token.colorBgContainer};
        }
        .quotation-summary-card .ant-statistic {
          padding: 18px 20px;
          border-radius: 18px;
          background: ${token.colorPrimaryBg};
          border: 1px solid ${token.colorPrimaryBorder};
        }
        .quotation-muted-block {
          padding: 14px 16px;
          border-radius: 16px;
          background: ${token.colorFillQuaternary};
          border: 1px solid ${token.colorBorderSecondary};
        }
        @media print {
          body.quotation-preview-printing > * {
            display: none !important;
          }
          body.quotation-preview-printing > .quotation-print-host {
            display: block !important;
          }
          body.quotation-preview-printing > .quotation-print-host {
            padding: 0 !important;
            margin: 0 !important;
            background: #fff !important;
          }
          body.quotation-preview-printing > .quotation-print-host * {
            visibility: visible !important;
          }
          body.quotation-preview-printing > .quotation-print-host .ant-card {
            break-inside: avoid;
          }
          body.quotation-preview-printing > .quotation-print-host table {
            width: 100% !important;
          }
          body.quotation-preview-printing > .quotation-print-host .ant-space {
            display: block !important;
          }
        }
      `}</style>
      <div style={{ marginBottom: 20 }}>
        <Space direction="vertical" size={8} style={{ width: '100%' }}>
          <Tag color="blue" style={{ alignSelf: 'flex-start', marginInlineEnd: 0, borderRadius: 999, paddingInline: 10 }}>
            Quotation workspace
          </Tag>
          <Title level={2} style={{ margin: 0 }}>
            Add quotation
          </Title>
          <Paragraph type="secondary" style={{ marginBottom: 0 }}>
            One page for customer context, product configuration, pricing summary, and quote notes.
          </Paragraph>
          <Text type="secondary" style={{ fontSize: 12 }}>
            Fields marked as Required need to be completed before saving.
          </Text>
        </Space>
      </div>

      {errorText ? (
        <Alert
          type="error"
          showIcon
          message={errorText}
          style={{ marginBottom: 16, borderRadius: 16 }}
        />
      ) : null}

      {saveResult ? (
        <Alert
          type="success"
          showIcon
          message={buildSuccessViewNode(
            `Quotation ${saveResult.quotationNo} saved with ${saveResult.itemCount} line(s), total ${money(saveResult.totalAmount)}.`,
            saveResult.viewPath,
          )}
          style={{ marginBottom: 16, borderRadius: 16 }}
        />
      ) : null}

      <Row gutter={[16, 16]}>
        <Col xs={24} xl={16}>
          <Space direction="vertical" size={16} style={{ width: '100%' }}>
            <Card
              className="quotation-soft-card"
              title={t("Basic information")}
              styles={{ body: { paddingBottom: 8 } }}
            >
              <Row gutter={[16, 16]}>
                <Col xs={24} md={12}>
                  <FieldLabel label={t("Quotation date")} required />
                  <DatePicker
                    value={form.quotation_date ? dayjs(form.quotation_date) : null}
                    onChange={(value) => updateFormValue('quotation_date', value ? value.format('YYYY-MM-DD') : '')}
                    status={!form.quotation_date ? 'error' : ''}
                    style={{ width: '100%' }}
                  />
                </Col>
                <Col xs={24} md={12}>
                  <FieldLabel label={t("Valid until")} required />
                  <DatePicker
                    value={form.valid_until ? dayjs(form.valid_until) : null}
                    onChange={(value) => updateFormValue('valid_until', value ? value.format('YYYY-MM-DD') : '')}
                    status={!form.valid_until ? 'error' : ''}
                    style={{ width: '100%' }}
                  />
                </Col>
                <Col xs={24} md={8}>
                  <FieldLabel label={t("Currency")} />
                  <Select
                    value={form.currency_code}
                    options={[
                      { label: 'CNY', value: 'CNY' },
                      { label: 'USD', value: 'USD' },
                      { label: 'EUR', value: 'EUR' },
                    ]}
                    onChange={(value) => updateFormValue('currency_code', value)}
                    style={{ width: '100%' }}
                  />
                </Col>
                <Col xs={24} md={8}>
                  <FieldLabel label={t("Status")} />
                  <Input value={currentStatusLabel} disabled />
                </Col>
                <Col xs={24} md={8}>
                  <FieldLabel label={t("Snapshot version")} />
                  <InputNumber
                    min={1}
                    style={{ width: '100%' }}
                    value={form.pricing_snapshot_version}
                    onChange={(value) => updateFormValue('pricing_snapshot_version', value)}
                  />
                </Col>
              </Row>
            </Card>

            <Card
              className="quotation-soft-card"
              title={t("Customer and contact")}
              styles={{ body: { paddingBottom: 8 } }}
            >
              <Row gutter={[16, 16]}>
                <Col xs={24} md={12}>
                  <FieldLabel label={t("Customer")} required />
                  <Select
                    showSearch
                    optionFilterProp="label"
                    value={form.customer_id}
                    placeholder={t("Select customer")}
                    status={!form.customer_id ? 'error' : ''}
                    options={customers.map((customer) => ({
                      label: customer.customer_name,
                      value: customer.id,
                    }))}
                    onChange={handleCustomerChange}
                    style={{ width: '100%' }}
                  />
                </Col>
                <Col xs={24} md={12}>
                  <FieldLabel label={t("Contact")} required />
                  <Select
                    showSearch
                    optionFilterProp="label"
                    value={form.contact_id}
                    placeholder={form.customer_id ? 'Select contact' : 'Select customer first'}
                    status={!form.contact_id ? 'error' : ''}
                    options={availableContacts.map((contact) => ({
                      label: contact.full_name,
                      value: contact.id,
                    }))}
                    onChange={handleContactChange}
                    style={{ width: '100%' }}
                  />
                </Col>
                <Col xs={24} md={12}>
                  <FieldLabel label={t("Contact email snapshot")} />
                  <Input
                    value={form.contact_email_snapshot}
                    onChange={(event) => updateFormValue('contact_email_snapshot', event.target.value)}
                  />
                </Col>
                <Col xs={24} md={12}>
                  <FieldLabel label={t("Contact phone snapshot")} />
                  <Input
                    value={form.contact_phone_snapshot}
                    onChange={(event) => updateFormValue('contact_phone_snapshot', event.target.value)}
                  />
                </Col>
                <Col xs={24}>
                  <FieldLabel label={t("Customer address snapshot")} />
                  <TextArea
                    value={form.customer_address_snapshot}
                    onChange={(event) => updateFormValue('customer_address_snapshot', event.target.value)}
                    autoSize={{ minRows: 2, maxRows: 4 }}
                  />
                </Col>
              </Row>

              {selectedCustomer || selectedContact ? (
                <React.Fragment>
                  <Divider />
                  <div className="quotation-muted-block">
                  <Descriptions column={1} size="small">
                    <Descriptions.Item label={t("Customer")}>
                      {selectedCustomer?.customer_name || '-'}
                    </Descriptions.Item>
                    <Descriptions.Item label={t("Contact")}>
                      {selectedContact?.full_name || '-'}
                    </Descriptions.Item>
                    <Descriptions.Item label={t("Owner")}>
                      {currentUser?.nickname || currentUser?.username || '#' + currentUser?.id}
                    </Descriptions.Item>
                  </Descriptions>
                  </div>
                </React.Fragment>
              ) : null}
            </Card>

            <Card
              className="quotation-soft-card"
              title={t("Quotation items")}
            >
              {items.length === 0 ? (
                <Empty description={t("No quotation lines yet")} />
              ) : (
                <Space direction="vertical" size={16} style={{ width: '100%' }}>
                  {items.map((item, index) => (
                    <Card
                      className="quotation-line-card"
                      key={item.localKey}
                      size="small"
                      styles={{ body: { paddingBottom: 8 } }}
                      title={
                        <Space size={10}>
                          <Tag color="geekblue" style={{ marginInlineEnd: 0 }}>
                            Line {index + 1}
                          </Tag>
                          <Text strong>{item.product_name_snapshot || t('Select product')}</Text>
                        </Space>
                      }
                      extra={
                        <Button
                          danger
                          type="text"
                          icon={<DeleteOutlined />}
                          onClick={() => removeItem(item.localKey)}
                        >
                          Remove
                        </Button>
                      }
                    >
                      <Row gutter={[16, 16]}>
                        <Col xs={24} md={12}>
                          <FieldLabel label={t("Product")} required />
                          <Select
                            showSearch
                            optionFilterProp="label"
                            value={item.product_id}
                            placeholder={t("Select product")}
                            status={itemHasContent(item) && !item.product_id ? 'error' : ''}
                            options={products.map((product) => ({
                              label: product.product_name + ' · ' + product.product_no,
                              value: product.id,
                            }))}
                            onChange={(value) => handleProductChange(item.localKey, value)}
                            style={{ width: '100%' }}
                          />
                        </Col>
                        <Col xs={24} md={6}>
                          <FieldLabel label={t("Quantity")} required />
                          <InputNumber
                            min={0}
                            style={{ width: '100%' }}
                            value={item.quantity_value}
                            status={itemHasContent(item) && toNumber(item.quantity_value) <= 0 ? 'error' : ''}
                            onChange={(value) => updateItem(item.localKey, { quantity_value: value })}
                          />
                        </Col>
                        <Col xs={24} md={6}>
                          <FieldLabel label={t("Unit")} />
                          <Input
                            value={item.unit_name}
                            onChange={(event) => updateItem(item.localKey, { unit_name: event.target.value })}
                          />
                        </Col>
                        <Col xs={24} md={12}>
                          <FieldLabel label={t("Pricing mode snapshot")} />
                          <Select
                            options={pricingModeOptions}
                            value={item.pricing_mode_snapshot}
                            onChange={(value) => updateItem(item.localKey, { pricing_mode_snapshot: value })}
                            style={{ width: '100%' }}
                          />
                        </Col>
                        <Col xs={24} md={6}>
                          <FieldLabel label={t("Base unit price")} />
                          <InputNumber
                            min={0}
                            style={{ width: '100%' }}
                            value={item.base_unit_price}
                            onChange={(value) => updateItem(item.localKey, { base_unit_price: value })}
                          />
                        </Col>
                        <Col xs={24} md={6}>
                          <FieldLabel label={t("Line discount")} />
                          <InputNumber
                            min={0}
                            style={{ width: '100%' }}
                            value={item.item_discount}
                            onChange={(value) => updateItem(item.localKey, { item_discount: value })}
                          />
                        </Col>
                        <Col xs={24} md={8}>
                          <FieldLabel label={t("Parameter surcharge")} />
                          <InputNumber
                            style={{ width: '100%' }}
                            value={calcParameterSurcharge(item)}
                            disabled
                          />
                        </Col>
                        <Col xs={24} md={8}>
                          <FieldLabel label={t("Accessory surcharge")} />
                          <InputNumber
                            style={{ width: '100%' }}
                            value={calcAccessorySurcharge(item)}
                            disabled
                          />
                        </Col>
                        <Col xs={24} md={8}>
                          <FieldLabel label={t("Service surcharge")} />
                          <InputNumber
                            min={0}
                            style={{ width: '100%' }}
                            value={item.service_surcharge}
                            onChange={(value) => updateItem(item.localKey, { service_surcharge: value })}
                          />
                        </Col>
                        <Col xs={24} md={12}>
                          <FieldLabel label={t("Parameter summary")} />
                          <TextArea
                            value={buildParameterSummary(item)}
                            disabled
                            autoSize={{ minRows: 2, maxRows: 4 }}
                          />
                        </Col>
                        <Col xs={24} md={12}>
                          <FieldLabel label={t("Service summary")} />
                          <TextArea
                            value={item.service_summary}
                            onChange={(event) => updateItem(item.localKey, { service_summary: event.target.value })}
                            autoSize={{ minRows: 2, maxRows: 4 }}
                          />
                        </Col>
                        <Col xs={24}>
                          <FieldLabel label={t("Line remark")} />
                          <TextArea
                            value={item.item_remark}
                            onChange={(event) => updateItem(item.localKey, { item_remark: event.target.value })}
                            autoSize={{ minRows: 2, maxRows: 4 }}
                          />
                        </Col>
                      </Row>

                      <Divider style={{ margin: '16px 0' }} />
                      <Collapse
                        ghost
                        size="small"
                        activeKey={normalizePanelKeys(item.openPanels)}
                        onChange={(keys) => updateItem(item.localKey, { openPanels: normalizePanelKeys(keys) })}
                        items={[
                          {
                            key: 'parameters',
