const { Table, Tag, Space, Typography, Tooltip, theme } = ctx.libs.antd;
const _ = ctx.libs.lodash;
const { useState, useEffect, useCallback, useRef } = ctx.libs.React;

const COLS = 11;
const PROJECT_STATUS_COLORS = {
  not_started: 'default', in_progress: 'blue', paused: 'gold',
  completed: 'green', delayed: 'orange', cancelled: 'red',
};
const PRIORITY_COLORS = { low: 'default', medium: 'blue', high: 'orange', urgent: 'red' };

const fmtNum = (v) => {
  const n = Number(v || 0);
  if (n >= 1e6) return '$' + (n / 1e6).toFixed(2) + 'M';
  if (n >= 1e3) return '$' + (n / 1e3).toFixed(1) + 'K';
  return '$' + n.toLocaleString('en-US', { maximumFractionDigits: 0 });
};

const _sanitizeFilter = (f) => {
  if (!f || typeof f !== 'object') return f;
  if (Array.isArray(f)) return f.map(_sanitizeFilter);
  const r = {};
  for (const k in f) {
    if (k === '$dateBetween' && typeof f[k] === 'string' && /^\d{4}-\d{2}$/.test(f[k])) {
      const [y, m] = f[k].split('-');
      const last = new Date(+y, +m, 0).getDate();
      r[k] = [`${f[k]}-01`, `${f[k]}-${String(last).padStart(2, '0')}`];
    } else {
      r[k] = _sanitizeFilter(f[k]);
    }
  }
  return r;
};

const calc = (rows) => {
  const budgets = rows.map(r => Number(r.budget_amount) || 0).filter(v => v > 0);
  const progresses = rows.map(r => {
    const p = Number(r.project_progress);
    return Number.isFinite(p) ? (p > 1 ? p : p * 100) : null;
  }).filter(p => p !== null);
  return {
    n: rows.length,
    budget: _.sum(budgets),
    budgetAvg: budgets.length ? _.mean(budgets) : 0,
    budgetMin: budgets.length ? _.min(budgets) : 0,
    budgetMax: budgets.length ? _.max(budgets) : 0,
    progAvg: progresses.length ? _.mean(progresses) : 0,
    delayed: rows.filter(r => r.project_status === 'delayed').length,
    active: rows.filter(r => r.project_status === 'in_progress').length,
  };
};

const Summary = () => {
  const { token } = theme.useToken();
  const [allData, setAllData] = useState([]);
  const [selectedRows, setSelectedRows] = useState([]);
  const patchedRef = useRef(false);

  const fetchAll = useCallback(async () => {
    try {
      const filter = _sanitizeFilter(ctx.resource.getFilter());
      if (ctx.flowSettingsEnabled) {
        ctx.sql.save({
          uid: 'summary_projects',
          sql: 'SELECT "id","actual_end_date","planned_end_date","start_date","createdAt","project_status","budget_amount","priority_level","project_progress" FROM "projects"',
          dataSourceKey: 'main',
        }).catch(() => {});
      }
      const items = await ctx.sql.runById('summary_projects', { filter, type: 'selectRows', dataSourceKey: 'main' });
      setAllData(items || []);
    } catch (e) { console.error('summary_projects fetch failed', e); }
  }, []);

  useEffect(() => {
    fetchAll();
    ctx.resource.on('refresh', fetchAll);
    setSelectedRows(ctx.resource?.getSelectedRows?.() || []);
    if (!patchedRef.current && ctx.resource?.setSelectedRows) {
      const orig = ctx.resource.setSelectedRows.bind(ctx.resource);
      ctx.resource.setSelectedRows = (rows) => { const r = orig(rows); setSelectedRows([...rows]); return r; };
      patchedRef.current = true;
    }
    return () => ctx.resource.off('refresh', fetchAll);
  }, []);

  const sel = calc(selectedRows);
  const all = calc(allData);

  const renderRow = (label, m, bg, color, accent) => (
    <Table.Summary.Row style={{ background: bg }}>
      <Table.Summary.Cell index={0} colSpan={1} />
      <Table.Summary.Cell index={1} colSpan={COLS - 1}>
        <Space size={6} wrap>
          <Typography.Text strong style={{ color, whiteSpace: 'nowrap', fontSize: 12 }}>{label}</Typography.Text>
          <Tag color={accent} style={{ margin: 0, fontSize: 11 }}>{m.n} {m.n === 1 ? 'row' : 'rows'}</Tag>
          {m.budget > 0 ? (
            <Tooltip title={`Avg ${fmtNum(m.budgetAvg)} · Min ${fmtNum(m.budgetMin)} · Max ${fmtNum(m.budgetMax)}`}>
              <Tag color="geekblue" style={{ margin: 0, fontSize: 11 }}>Budget: {fmtNum(m.budget)}</Tag>
            </Tooltip>
          ) : null}
          {m.progAvg > 0 ? <Tag color="cyan" style={{ margin: 0, fontSize: 11 }}>Avg progress: {m.progAvg.toFixed(0)}%</Tag> : null}
          {m.active > 0  ? <Tag color="processing" style={{ margin: 0, fontSize: 11 }}>Active: {m.active}</Tag> : null}
          {m.delayed > 0 ? <Tag color="orange" style={{ margin: 0, fontSize: 11 }}>Delayed: {m.delayed}</Tag> : null}
        </Space>
      </Table.Summary.Cell>
    </Table.Summary.Row>
  );

  return (
    <Table.Summary fixed>
      {sel.n > 0 ? renderRow('Selected', sel, token.colorPrimaryBg, token.colorPrimary, 'blue') : null}
      {renderRow('All', all, token.colorFillQuaternary, token.colorText, 'default')}
      <Table.Summary.Row style={{ background: token.colorFillQuaternary }}>
        <Table.Summary.Cell index={0} colSpan={1} />
        <Table.Summary.Cell index={1} colSpan={COLS - 1}>
          <Space size={4} wrap>
            <Typography.Text type="secondary" style={{ fontSize: 11 }}>Status:</Typography.Text>
            {Object.entries(_.countBy(allData, r => r.project_status || 'N/A'))
              .sort(([, a], [, b]) => b - a)
              .map(([k, count]) => {
                const amt = _.sumBy(allData.filter(r => r.project_status === k), r => Number(r.budget_amount) || 0);
                return (
                  <Tooltip key={k} title={`${k}: ${count} projects · ${fmtNum(amt)}`}>
                    <Tag color={PROJECT_STATUS_COLORS[k] || 'default'} style={{ margin: 0, fontSize: 11 }}>{k}: {count}</Tag>
                  </Tooltip>
                );
              })}
            <Typography.Text type="secondary" style={{ fontSize: 11, marginLeft: 12 }}>Priority:</Typography.Text>
            {Object.entries(_.countBy(allData, r => r.priority_level || 'N/A'))
              .sort(([, a], [, b]) => b - a)
              .map(([p, count]) => (
                <Tag key={p} color={PRIORITY_COLORS[p] || 'default'} style={{ margin: 0, fontSize: 11 }}>{p}: {count}</Tag>
              ))}
          </Space>
        </Table.Summary.Cell>
      </Table.Summary.Row>
    </Table.Summary>
  );
};

